from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    separator = Counter(v for row in grid for v in row if v != 0).most_common(1)[0][0]
    sep_rows = [r for r, row in enumerate(grid) if all(v == separator for v in row)]
    sep_cols = [c for c in range(w) if all(grid[r][c] == separator for r in range(h))]

    def spans(length, separators):
        out, start = [], 0
        for pos in separators:
            if start < pos:
                out.append(list(range(start, pos)))
            start = pos + 1
        if start < length:
            out.append(list(range(start, length)))
        return out

    row_cells = spans(h, sep_rows)
    col_cells = spans(w, sep_cols)
    color_counts = Counter(v for row in grid for v in row if v not in (0, separator))
    pattern_color = color_counts.most_common(1)[0][0]
    pattern = None
    for rs in row_cells:
        for cs in col_cells:
            points = [(i, j) for i, r in enumerate(rs) for j, c in enumerate(cs)
                      if grid[r][c] == pattern_color]
            if points:
                pattern = points
                break
        if pattern is not None:
            break

    row_colors = []
    for rs in row_cells:
        first = col_cells[0]
        colors = [grid[r][c] for r in rs for c in first
                  if grid[r][c] not in (0, separator, pattern_color)]
        row_colors.append(Counter(colors).most_common(1)[0][0])

    result = [[0 for _ in range(w)] for _ in range(h)]
    for r in sep_rows:
        result[r] = [separator] * w
    for c in sep_cols:
        for r in range(h):
            result[r][c] = separator
